+QJsonObject DeclarativeHistoryModel::shareData(const QString &uuid)
+{
+    const qsizetype row = m_model->indexOf(uuid);
+    if (row < 0) {
+        return {};
+    }
+    const auto &item = m_model->m_items[row];
+
+    // Purpose plugins share files, so text and images are shared as files with a readable name
+    auto shareFilePath = [this, &uuid](const QString &fileName) -> QString {
+        if (!m_shareDir) {
+            m_shareDir = std::make_unique<QTemporaryDir>();
+        }
+        if (!m_shareDir->isValid() || !QDir(m_shareDir->path()).mkpath(uuid)) {
+            return {};
+        }
+        const QString path = m_shareDir->filePath(uuid + u'/' + fileName);
+        QFile::remove(path);
+        return path;
+    };
+
+    QList<QUrl> urls;
+    QString mimeType;
+    switch (item->type()) {
+    case HistoryItemType::Url:
+        for (const QStringList parts = item->text().split(u' ', Qt::SkipEmptyParts); const QString &part : parts) {
+            urls.append(QUrl::fromEncoded(part.toUtf8()));
+        }
+        break;
+    case HistoryItemType::Text: {
+        const QString text = item->text();
+        if (const QUrl url(text.trimmed(), QUrl::StrictMode); url.isValid() && (url.scheme() == u"http" || url.scheme() == u"https")) {
+            urls.append(url);
+            break;
+        }
+        QFile file(shareFilePath(u"clipboard.txt"_s));
+        if (file.fileName().isEmpty() || !file.open(QIODevice::WriteOnly) || file.write(text.toUtf8()) < 0) {
+            return {};
+        }
+        urls.append(QUrl::fromLocalFile(file.fileName()));
+        mimeType = u"text/plain"_s;
+        break;
+    }
+    case HistoryItemType::Image: {
+        const QString source = m_model->index(row).data(HistoryModel::ImageUrlRole).toUrl().toLocalFile();
+        const QMimeType type = QMimeDatabase().mimeTypeForFile(source, QMimeDatabase::MatchContent);
+        const QString path = shareFilePath(u"image."_s + type.preferredSuffix());
+        if (source.isEmpty() || path.isEmpty() || !QFile::copy(source, path)) {
+            return {};
+        }
+        urls.append(QUrl::fromLocalFile(path));
+        mimeType = type.name();
+        break;
+    }
+    default:
+        return {};
+    }
+
+    if (mimeType.isEmpty()) {
+        QMimeDatabase db;
+        for (const QUrl &url : std::as_const(urls)) {
+            const QString urlMimeType = url.isLocalFile() ? db.mimeTypeForUrl(url).name() : u"text/x-uri"_s;
+            if (mimeType.isEmpty()) {
+                mimeType = urlMimeType;
+            } else if (mimeType != urlMimeType) {
+                mimeType = u"application/octet-stream"_s;
+                break;
+            }
+        }
+    }
+
+    QJsonArray urlArray;
+    for (const QUrl &url : std::as_const(urls)) {
+        if (url.isValid()) {
+            urlArray.append(url.toString());
+        }
+    }
+    if (urlArray.isEmpty()) {
+        return {};
+    }
+    return {{u"urls"_s, urlArray}, {u"mimeType"_s, mimeType}};
+}
