+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Templates as T
+import QtQuick.Layouts
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+import org.kde.kirigami as Kirigami
+
+import org.kde.purpose as Purpose
+
+Item {
+    id: shareView
+
+    required property T.StackView stack
+    required property var inputData
+    required property bool showHeader
+
+    Keys.onPressed: event => {
+        if (event.key == Qt.Key_Escape) {
+            shareView.stack.popCurrentItem();
+            event.accepted = true;
+        }
+    }
+
+    property PlasmaExtras.PlasmoidHeading header: PlasmaExtras.PlasmoidHeading {
+        visible: shareView.showHeader
+        RowLayout {
+            anchors.fill: parent
+            PlasmaComponents3.ToolButton {
+                icon.name: "go-previous-view"
+                text: i18nd("klipper", "Return to Clipboard")
+                onClicked: {
+                    shareView.stack.popCurrentItem()
+                    shareView.stack.forceActiveFocus(Qt.OtherFocusReason)
+                }
+                visible: shareView.showHeader
+            }
+
+            Item {
+                Layout.fillWidth: true
+            }
+        }
+    }
+
+    Purpose.AlternativesView {
+        id: alternatives
+
+        anchors.fill: parent
+        anchors.margins: Kirigami.Units.smallSpacing
+        visible: errorMessage.text.length === 0
+
+        pluginType: "Export"
+        inputData: shareView.inputData
+        focus: true
+
+        delegate: PlasmaComponents3.ItemDelegate {
+            required property var model
+            required property int index
+
+            width: ListView.view.width
+            text: model.display
+            icon.name: model.iconName
+            onClicked: alternatives.createJob(index)
+            Keys.onReturnPressed: clicked()
+            Keys.onEnterPressed: clicked()
+        }
+
+        onFinished: (output, error, message) => {
+            // 1 is KIO::ERR_USER_CANCELED
+            if (error !== 0 && error !== 1) {
+                errorMessage.text = message;
+                return;
+            }
+            alternatives.reset();
+            if (error === 0) {
+                shareView.stack.popCurrentItem();
+            }
+        }
+    }
+
+    PlasmaExtras.PlaceholderMessage {
+        id: errorMessage
+        anchors.centerIn: parent
+        width: parent.width - (Kirigami.Units.gridUnit * 4)
+        visible: text.length > 0
+        iconName: "dialog-error"
+        text: shareView.inputData.urls ? "" : i18nd("klipper", "This item cannot be shared")
+    }
+}
